function can(k){if(ADMIN)return true;var p=FLAGS.perms||A.perms;return !!(p&&p[k]&&!p.disabled)}
function inv(action,body){return DFA.invoke('admission',Object.assign({action:action},body||{}))}
function err(r,fb){return (r&&r.data&&r.data.error)||(r&&r.error&&(r.error.message||String(r.error)))||fb}
