/* ---------- privacy masking ---------- */
function maskEmail(v){var s=String(v),i=s.indexOf('@');if(i<1)return s.slice(0,1)+'•••';var u=s.slice(0,i),dm=s.slice(i+1),j=dm.lastIndexOf('.');return u.slice(0,1)+'•••@'+dm.slice(0,1)+'•••'+(j>0?dm.slice(j):'')}
function maskPhone(v){var s=String(v).replace(/\s+/g,'');return s.length<5?'•••':s.slice(0,3)+'•••'+s.slice(-2)}
function maskIp(v){var s=String(v);if(s.indexOf(':')>=0)return s.split(':').slice(0,2).join(':')+':•••';var p=s.split('.');return p.length===4?p[0]+'.'+p[1]+'.•••.•••':'•••'}
function mask(v,kind){if(!v)return '';var s=kind==='email'?maskEmail(v):kind==='ip'?maskIp(v):maskPhone(v);return '<button type="button" class="adm-mask" data-full="'+E(v)+'" data-m="'+E(s)+'" aria-label="Show hidden '+kind+'" title="Hidden for privacy. Click to show, click again to hide.">'+E(s)+'</button>'}
/* staff rows arrive masked from the server (pro_students); the real value comes from pro_reveal, which logs who looked */
function rmask(masked,kind,id){if(!masked)return '';return '<button type="button" class="adm-mask" data-rid="'+(+id)+'" data-f="'+(kind==='email'?'email':'phone')+'" data-m="'+E(masked)+'" aria-label="Show hidden '+kind+'" title="Hidden for privacy. Click to show it (this is saved in the activity log with your name).">'+E(masked)+'</button>'}
function reveal(id,field,why){if(!can('see_contacts'))return Promise.reject(new Error('You cannot see contact details. Ask an admin.'));return inv('pro_reveal',{id:id,field:field,why:why||''}).then(function(r){if(r.data&&r.data.ok)return r.data.value||'';throw new Error(err(r,'Could not show it.'))})}
document.addEventListener('click',async function(ev){var b=ev.target.closest&&ev.target.closest('.adm-mask');if(!b)return;ev.preventDefault();
 if(b.dataset.rid&&b.dataset.full==null){if(b.disabled)return;b.disabled=true;try{b.dataset.full=await reveal(+b.dataset.rid,b.dataset.f,'card')}catch(e){b.disabled=false;return alert(e.message)}b.disabled=false}
 var on=b.classList.toggle('on');b.textContent=on?b.dataset.full:b.dataset.m});
function privacyOn(){try{return localStorage.getItem('dfa-adm-privacy')==='1'}catch(e){return false}}

/* ---------- dialogs ---------- */
function confirmDlg(o){return new Promise(function(res){var done=false;function fin(v){if(!done){done=true;res(v)}}
 var g=dlg('<h3>'+E(o.title)+'</h3><div class="adm-warnbox">'+o.html+'</div>'+(o.reason?'<label class="adm-fl">Reason (kept in the activity log)<textarea name="reason" required minlength="3" maxlength="300" rows="2" title="Why you are doing this. Saved with your name and the time."></textarea></label>':'')+(o.word?'<label class="adm-fl">Type <b>'+E(o.word)+'</b> to confirm<input name="word" autocomplete="off" autocapitalize="characters" spellcheck="false" required title="Type the word exactly to unlock the button. This protects against a misclick."></label>':''));
 var f=g.querySelector('form'),ok=f.querySelector('[value=ok]');ok.textContent=o.ok||'Confirm';ok.classList.add('danger');ok.title='Do it now.';
 function chk(){ok.disabled=!!o.word&&f.word.value.trim().toUpperCase()!==o.word}f.addEventListener('input',chk);chk();
 f.onsubmit=function(ev){if(ev.submitter&&ev.submitter.value==='cancel'){fin(null);return}ev.preventDefault();if(!f.reportValidity())return;fin({reason:f.reason?f.reason.value.trim():'',word:f.word?f.word.value.trim().toUpperCase():'',g:g,m:g.querySelector('.adm-dmsg'),ok:ok})};
 g.addEventListener('close',function(){fin(null)})})}
/* runs an action from a confirm dialog and keeps it open on error */
async function runIn(c,fn){c.ok.disabled=true;c.m.textContent='Working…';try{var r=await fn();if(r&&r.data&&r.data.ok){c.g.close();return r}c.m.textContent=err(r,'Something went wrong.');c.ok.disabled=false;return null}catch(e){c.m.textContent=String(e&&e.message||e);c.ok.disabled=false;return null}}

/* ---------- counts on the filter chips (cached 30 s) ---------- */
var CC=null,CCat=0,CCp=null;
function counts(force){if(!force&&CC&&Date.now()-CCat<30000)return Promise.resolve(CC);if(CCp&&!force)return CCp;var t=today();
 if(!ADMIN){CCp=inv('pro_students',{mode:'counts'}).then(function(r){CC=(r.data&&r.data.counts)||{};CCat=Date.now();CCp=null;return CC},function(){CCp=null;return {}});return CCp}
 function c(fn){var q=sb.from('enrollments').select('id',{count:'exact',head:true});q=fn?fn(q):q;return q.then(function(r){return r.count||0},function(){return null})}
 CCp=Promise.all([c(),c(function(q){return q.eq('status','pending')}),c(function(q){return q.eq('status','active')}),c(function(q){return q.gt('balance_due',0).in('status',['active','expired'])}),c(function(q){return q.gt('balance_due',0).in('status',['active','expired']).lt('due_date',t)}),c(function(q){return q.eq('status','expired')}),c(function(q){return q.eq('status','revoked')}),sb.from('student_meta').select('enrollment_id',{count:'exact',head:true}).eq('is_test',true).then(function(r){return r.count||0},function(){return null})])
  .then(function(a){CC={all:a[0],pending:a[1],active:a[2],'fee pending':a[3],overdue:a[4],expired:a[5],revoked:a[6],test:a[7]};CCat=Date.now();CCp=null;return CC});return CCp}
function invalidate(){CCat=0;BATCHES=null}

/* ---------- batches cache ---------- */
var BATCHES=null;
async function batches(force){if(BATCHES&&!force)return BATCHES;var r=await sb.from('batches').select('*').order('start_date',{ascending:false});BATCHES=r.error?[]:(r.data||[]);return BATCHES}
function bLabel(b){return b.code+' · '+cname(b.course_code)+' · '+d(b.start_date)+(b.time_slot?' · '+SLOTS[b.time_slot]:'')+(b.status!=='planned'&&b.status!=='running'?' ('+b.status+')':'')}

/* students for the batch screens: admins read the table, staff get the masked list from the server */
async function enrList(o){if(ADMIN){var q=sb.from('enrollments').select(o.cols);if(o.batch==='none')q=q.is('batch_id',null);else if(o.batch)q=q.eq('batch_id',o.batch);if(o.status)q=q.in('status',o.status);if(o.notRevoked)q=q.neq('status','revoked');return q.order('full_name').limit(500)}
 var r=await inv('pro_students',{batch:o.batch,status:o.status||(o.notRevoked?['pending','active','expired']:null),filter:'all',sort:'full_name.asc',size:500,pays:false});return r.data&&r.data.ok?{data:r.data.rows}:{data:[],error:{message:err(r,'Could not load the students.')}}}
/* =================================================================================================
   Student list helpers (used by dfa-admin.js enr())
   ================================================================================================= */
var CHIPH={all:'Every student.',pending:'Registered, payment not confirmed yet.',active:'Paid; portal and books open.','fee pending':'Active or expired students who still owe money.',overdue:'Students whose due date has passed and who still owe money.',expired:'Access period is over.',revoked:'Access removed by staff.',test:'Records marked TEST (left out of the dashboard, exports and reminders).'};
var CHIPS=[['all','All'],['pending','Pending'],['active','Active'],['fee pending','Fee pending'],['overdue','Overdue'],['expired','Expired'],['revoked','Revoked'],['test','TEST']];
function applyFilter(q,f){var t=today();if(f==='fee pending')return q.gt('balance_due',0).in('status',['active','expired']);if(f==='overdue')return q.gt('balance_due',0).in('status',['active','expired']).lt('due_date',t);if(f==='all'||f==='test')return q;return q.eq('status',f)}
function orSearch(s){var v=String(s).replace(/[,()*%\\]/g,' ').trim().slice(0,60);if(!v)return null;var p='*'+v+'*';return ['full_name','email','phone','student_id','batch_code','invoice_no','certificate_no'].map(function(k){return k+'.ilike.'+p}).join(',')}
var SORTS={'created_at.desc':'Newest first','created_at.asc':'Oldest first','full_name.asc':'Name A–Z','due_date.asc':'Next due date','balance_due.desc':'Highest balance'};
/** Runs the paged, sorted, searched student query. ST: {filter,q,sort,page,size,batch,tag} */
var FLAGS={staff_payments:false,perms:A.perms||null};
async function studentQuery(ST){var ids=null;
 if(!ADMIN){var rs=await inv('pro_students',{filter:ST.filter,q:ST.q,sort:ST.sort,page:ST.page,size:ST.size,batch:ST.batch,tag:ST.tag});if(!(rs.data&&rs.data.ok))return {error:{message:err(rs,'Could not load the students.')}};FLAGS=Object.assign({perms:A.perms||null},rs.data.flags||FLAGS);if(!FLAGS.perms)FLAGS.perms=A.perms||null;return {data:rs.data.rows,count:rs.data.count,pays:rs.data.pays}}
 if(ST.filter==='test'||ST.tag){var mq=sb.from('student_meta').select('enrollment_id');if(ST.filter==='test')mq=mq.eq('is_test',true);if(ST.tag)mq=mq.contains('tags',[ST.tag]);var mr=await mq;ids=(mr.data||[]).map(function(m){return m.enrollment_id});if(!ids.length)return {data:[],count:0}}
 var q=sb.from('enrollments').select('*',{count:'exact'});q=applyFilter(q,ST.filter);if(ids)q=q.in('id',ids);
 var os=ST.q&&orSearch(ST.q);if(os)q=q.or(os);
 if(ST.batch==='none')q=q.is('batch_id',null);else if(ST.batch)q=q.eq('batch_id',+ST.batch);
 var s=(ST.sort||'created_at.desc').split('.');q=q.order(s[0],{ascending:s[1]==='asc',nullsFirst:false});if(s[0]!=='created_at')q=q.order('created_at',{ascending:false});
 return q.range(ST.page*ST.size,ST.page*ST.size+ST.size-1)}
async function allTags(){var r=await sb.from('student_meta').select('tags').limit(2000);var s={};(r.data||[]).forEach(function(m){(m.tags||[]).forEach(function(t){s[t]=1})});return Object.keys(s).sort()}
async function barHtml(ST,total){var cc=await counts(),bs=await batches(),tg=await allTags();
 var chips='<div class="adm-chips" role="group" aria-label="Filter students"'+T('chips')+'>'+CHIPS.filter(function(c){return c[0]!=='test'||ADMIN||cc.test}).map(function(c){var n=cc[c[0]];return '<button type="button" class="adm-chip'+(ST.filter===c[0]?' on':'')+(c[0]==='overdue'&&n?' warn':'')+'" data-chip="'+E(c[0])+'" aria-pressed="'+(ST.filter===c[0])+'" title="'+E(CHIPH[c[0]]||'')+'">'+c[1]+(n==null?'':' <b>'+n+'</b>')+'</button>'}).join('')+'</div>';
 var pages=Math.max(1,Math.ceil(total/ST.size));
 return chips+'<div class="adm-bar adm-bar2x"><input type="search" id="enq" class="adm-q" value="'+E(ST.q)+'" placeholder="Search name, email, phone, ID, batch, invoice" aria-label="Search students"'+T('search')+'>'+
  '<label class="adm-mut adm-nw">Sort <select id="ens"'+T('sort')+'>'+Object.keys(SORTS).map(function(k){return '<option value="'+k+'"'+(ST.sort===k?' selected':'')+'>'+SORTS[k]+'</option>'}).join('')+'</select></label>'+
  '<label class="adm-mut adm-nw">Batch <select id="enb"'+T('bfilter')+'><option value="">All batches</option><option value="none"'+(ST.batch==='none'?' selected':'')+'>No batch</option>'+bs.map(function(b){return '<option value="'+b.id+'"'+(String(ST.batch)===String(b.id)?' selected':'')+'>'+E(b.code)+'</option>'}).join('')+'</select></label>'+
  (tg.length?'<label class="adm-mut adm-nw">Tag <select id="ent"'+T('tfilter')+'><option value="">Any tag</option>'+tg.map(function(t){return '<option'+(ST.tag===t?' selected':'')+'>'+E(t)+'</option>'}).join('')+'</select></label>':'')+
  '<span class="adm-mut" data-found>'+total+' found</span><span class="adm-sp"></span>'+
  (can('add_students')?'<button type="button" class="btn outline sm" id="enadd"'+T('add')+'>Add student</button>':'')+(can('export')?'<button type="button" class="btn outline sm" data-p="export"'+T('exportBtn')+'>Export</button>':'')+
  (ADMIN?'<label class="adm-ck adm-nw"'+T('privacy')+'><input type="checkbox" id="enpriv"'+(privacyOn()?' checked':'')+'> Hide contacts</label>':'')+'</div>'+
  '<div id="enform"></div>'+pager(ST,total,pages,'top')}
function pager(ST,total,pages,pos){if(total<=ST.size&&pos==='top')return '';return '<div class="adm-pager" data-pager="'+pos+'"><button type="button" class="btn outline sm" data-pg="-1"'+(ST.page<=0?' disabled':'')+T('page')+'>‹ Previous</button><span class="adm-mut">Page '+(ST.page+1)+' of '+pages+' · '+total+' students</span><button type="button" class="btn outline sm" data-pg="1"'+(ST.page+1>=pages?' disabled':'')+T('page')+'>Next ›</button><label class="adm-mut adm-nw">Show <select data-size'+T('size')+'>'+[25,50,100].map(function(n){return '<option'+(ST.size===n?' selected':'')+'>'+n+'</option>'}).join('')+'</select></label></div>'}
/** Wires chips, search (debounced), sort, filters, pager. go(patch) re-runs the list. */
function wireBar(B,ST,go){var tm=null;
 B.querySelectorAll('[data-chip]').forEach(function(b){b.onclick=function(){go({filter:b.dataset.chip,page:0})}});
 var q=B.querySelector('#enq');if(q){q.oninput=function(){clearTimeout(tm);tm=setTimeout(function(){go({q:q.value.trim(),page:0},true)},350)};q.onkeydown=function(e){if(e.key==='Enter'){clearTimeout(tm);go({q:q.value.trim(),page:0},true)}}}
 [['#ens','sort'],['#enb','batch'],['#ent','tag']].forEach(function(p){var s=B.querySelector(p[0]);if(s)s.onchange=function(){var o={page:0};o[p[1]]=s.value;go(o)}});
 B.querySelectorAll('[data-pg]').forEach(function(b){b.onclick=function(){go({page:Math.max(0,ST.page+ +b.dataset.pg)});scrollTo({top:0,behavior:'smooth'})}});
 B.querySelectorAll('[data-size]').forEach(function(s){s.onchange=function(){go({size:+s.value,page:0})}});
 var pv=B.querySelector('#enpriv');if(pv)pv.onchange=function(){try{localStorage.setItem('dfa-adm-privacy',pv.checked?'1':'0')}catch(e){}go({})};
 var ex=B.querySelector('[data-p=export]');if(ex)ex.onclick=function(){exportDlg(ST)}}

/* ---------- per-payment reference + proof (inside the payment history list) ---------- */
function proofOk(p){return !!(p.proof_file||/^https:\/\/drive\.google\.com\/(open\?id=|file\/d\/)[\w-]{15,}/.test(String(p.proof_url||'')))}
function histExtra(p){if(!p||!p.id||p.voided_at)return p&&p.reference?'<span class="adm-mut adm-nw">Ref '+E(p.reference)+'</span>':'';
 return (p.reference?'<span class="adm-mut adm-nw"'+T('ref')+'>Ref '+E(p.reference)+'</span>':'')+(proofOk(p)?'<button type="button" class="adm-lnk" data-p="proof-view" data-pid="'+p.id+'"'+T('proofView')+'>Proof</button>':'')+'<button type="button" class="adm-lnk" data-p="proof-add" data-pid="'+p.id+'"'+T('proofAdd')+'>'+(p.reference||proofOk(p)?'Edit ref/proof':'Add ref/proof')+'</button>'}
async function shrink(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size<1.2e6)return file;try{var bm=await createImageBitmap(file),s=Math.min(1,1800/Math.max(bm.width,bm.height)),c=document.createElement('canvas');c.width=Math.round(bm.width*s);c.height=Math.round(bm.height*s);c.getContext('2d').drawImage(bm,0,0,c.width,c.height);var b=await new Promise(function(r){c.toBlob(r,'image/jpeg',0.82)});return b&&b.size<file.size?new File([b],'proof.jpg',{type:'image/jpeg'}):file}catch(e){return file}}
async function uploadProof(pid,file,ref){file=await shrink(file);if(file.size>5*1024*1024)throw new Error('The file must be smaller than 5 MB.');
 var r=await inv('pro_proof_upload',{payment_id:pid,type:file.type,size:file.size});if(!r.data||!r.data.ok)throw new Error(err(r,'Could not prepare the upload.'));
 var u=await sb.storage.from('documents').uploadToSignedUrl(r.data.path,r.data.token,file,{contentType:file.type});if(u.error)throw new Error(u.error.message);
 var a=await inv('pro_proof_attach',{payment_id:pid,path:r.data.path,reference:ref});if(!a.data||!a.data.ok)throw new Error(err(a,'Could not save the proof.'));return true}
function payFields(){return '<label class="adm-fl">Transaction ID / reference (optional)<input name="ref" maxlength="80" autocomplete="off" placeholder="e.g. TID 01234567"'+T('ref')+'></label><label class="adm-fl">Payment slip (optional)<input type="file" name="pfile" accept="image/jpeg,image/png,image/webp,application/pdf"'+T('proofFile')+'></label>'}
function proofDlg(p,after){var g=dlg('<h3>Reference and payment slip</h3><p class="adm-mut">Payment '+E(p.invoice_no||'')+' · '+E(pk(p.amount))+' · '+E(d(String(p.paid_on||'').slice(0,10)))+'</p><label class="adm-fl">Transaction ID / reference<input name="ref" maxlength="80" autocomplete="off" value="'+E(p.reference||'')+'"'+T('ref')+'></label><label class="adm-fl">'+(proofOk(p)?'Replace the payment slip (optional)':'Payment slip')+'<input type="file" name="pfile" accept="image/jpeg,image/png,image/webp,application/pdf"'+T('proofFile')+'></label>');
 var f=g.querySelector('form'),m=g.querySelector('.adm-dmsg'),ok=f.querySelector('[value=ok]');ok.textContent='Save';
 f.onsubmit=async function(ev){if(ev.submitter&&ev.submitter.value==='cancel')return;ev.preventDefault();ok.disabled=true;m.textContent='Saving…';
  try{var file=f.pfile.files[0];if(file)await uploadProof(p.id,file,f.ref.value);else{var r=await inv('pro_payment_ref',{payment_id:p.id,reference:f.ref.value});if(!r.data||!r.data.ok)throw new Error(err(r,'Could not save.'))}g.close();toast('Saved');after&&after()}catch(e){m.textContent=e.message;ok.disabled=false}}}
async function openProof(pid){var w=window.open('','_blank');var r=await inv('pro_proof_url',{payment_id:pid});if(r.data&&r.data.url){if(w)w.location=r.data.url;else location.href=r.data.url}else{if(w)w.close();alert(err(r,'No payment slip saved.'))}}

/* =================================================================================================
   Card decoration: More menu, class/notes/tags section, adjustments, staff limits, privacy
   ================================================================================================= */
async function decorate(B,rows,PAYS,refresh){if(!rows.length)return;var ids=rows.map(function(x){return x.id});
 var R=await Promise.all([sb.from('student_meta').select('*').in('enrollment_id',ids),sb.from('student_notes').select('*').in('enrollment_id',ids).order('pinned',{ascending:false}).order('created_at',{ascending:false}).limit(500),sb.from('attendance_summary').select('*').in('enrollment_id',ids),sb.from('fee_adjustments').select('*').in('enrollment_id',ids).order('created_at'),batches()]);
 var META={},NOTES={},ATT={},ADJS={};(R[0].data||[]).forEach(function(m){META[m.enrollment_id]=m});(R[1].data||[]).forEach(function(n){(NOTES[n.enrollment_id]=NOTES[n.enrollment_id]||[]).push(n)});(R[2].data||[]).forEach(function(a){ATT[a.enrollment_id]=a});(R[3].data||[]).forEach(function(a){(ADJS[a.enrollment_id]=ADJS[a.enrollment_id]||[]).push(a)});var BS=R[4];
 var priv=privacyOn();
 rows.forEach(function(x){var card=B.querySelector('.adm-card[data-id="'+x.id+'"]');if(!card)return;var mt=META[x.id]||{},pend=x.status==='pending',act=x.status==='active'||x.status==='expired';
  card._x=x;card._meta=mt;card._notes=NOTES[x.id]||[];card._adjs=ADJS[x.id]||[];
  // header badges
  var tg=card.querySelector('.adm-tags');if(tg){var hb='';if(mt.is_test)hb+='<span class="adm-st st-test"'+T('markTest')+'>TEST</span>';var at=ATT[x.id];if(at&&at.pct!=null)hb+='<span class="adm-fee '+(at.pct>=75?'ok':at.pct>=50?'pp':'od')+'"'+T('att')+'>Attendance '+at.pct+'%</span>';if(mt.reminders_paused)hb+='<span class="adm-tag"'+T('pauseRem')+'>Reminders paused</span>';tg.insertAdjacentHTML('beforeend',hb)}
  // staff: hide admin-only buttons (the server refuses them anyway)
  if(!ADMIN){var hide=[('[data-a=pay]'),('[data-a=plan]'),('[data-a=fix]'),('[data-a=regen]'),('[data-a=cert]'),('[data-a=hold]'),('[data-a=crev]'),('[data-a=rev]')];
    if(!can('edit_student_info'))hide.push('[data-a=info]','a.adm-pill[href^="doc.html"]','[data-doc]');
    if(!can('documents_emails'))hide.push('[data-a=resend]','[data-a=docs]','[data-p=resend]');
    if(!can('notes_tags'))hide.push('[data-p=note]','[data-p=tag]','[data-a=note]');
    if(!can('reminders'))hide.push('[data-p=pause]','[data-p=resume]');
    if(!can('discounts_refunds'))hide.push('[data-p=adj]','[data-p=adj-void]','[data-a=adj]');
    if(!can('batches'))hide.push('[data-p=batch]','[data-a=batch]');
    if(!can('open_payment_slips'))hide.push('[data-p=proof]','[data-p=proof-open]');
    card.querySelectorAll(hide.join(',')).forEach(function(b){b.remove()})}
  // payment recording is off unless this staff member has record_payments (default off)
  if(!ADMIN&&!can('record_payments'))card.querySelectorAll('[data-a=inst],[data-p=proof-add]').forEach(function(b){b.remove()});
  // privacy: staff rows are masked by the server (click = logged reveal); admins can hide contacts on screen
  if(x.masked)card.querySelectorAll('.adm-r').forEach(function(r){var k=(r.querySelector('dt')||{}).textContent||'';var dd=r.querySelector('dd');if(!dd)return;if(/^Email/.test(k))dd.innerHTML=rmask(x.email,'email',x.id);else if(/^Mobile/.test(k))dd.innerHTML=rmask(x.phone,'phone',x.id)});
  else if(priv)card.querySelectorAll('.adm-r').forEach(function(r){var k=(r.querySelector('dt')||{}).textContent||'';var dd=r.querySelector('dd');if(!dd)return;if(/^Email/.test(k))dd.innerHTML=mask(x.email,'email');else if(/^Mobile/.test(k))dd.innerHTML=mask(x.phone,'phone')});
  // class, notes and tags
  var secs=card.querySelector('.adm-secs');if(secs&&!pend){var bopts=BS.filter(function(b){return b.course_code===x.course_code&&(b.status==='planned'||b.status==='running'||b.id===x.batch_id)}),other=BS.filter(function(b){return bopts.indexOf(b)<0&&(b.status==='planned'||b.status==='running'||b.id===x.batch_id)});
   var bsel='<select data-p="batch"'+T('batchPick')+' aria-label="Batch"><option value="">No batch'+(x.batch_id?'':' ('+E(x.batch_code||'–')+')')+'</option>'+bopts.map(function(b){return '<option value="'+b.id+'"'+(b.id===x.batch_id?' selected':'')+'>'+E(bLabel(b))+'</option>'}).join('')+(other.length?'<optgroup label="Other courses">'+other.map(function(b){return '<option value="'+b.id+'"'+(b.id===x.batch_id?' selected':'')+'>'+E(bLabel(b))+'</option>'}).join('')+'</optgroup>':'')+'</select>';
   var at2=ATT[x.id],att=at2?'<span class="adm-nw"><b>'+(at2.pct==null?'–':at2.pct+'%')+'</b> · '+at2.present+' present, '+at2.late+' late, '+at2.absent+' absent'+(at2.excused?', '+at2.excused+' excused':'')+'</span>':'<span class="adm-mut">No classes marked yet</span>';
   var tags=(mt.tags||[]).map(function(t){return '<span class="adm-tagchip">'+E(t)+'</span>'}).join('')+'<button type="button" class="adm-lnk" data-p="tags"'+T('tags')+'>'+((mt.tags||[]).length?'Edit':'Add tags')+'</button>';
   var ns=card._notes,nh=ns.slice(0,2).map(function(n){return '<li'+(n.pinned?' class="pin"':'')+'><span>'+E(n.body)+'</span><small class="adm-mut">'+E(d(n.created_at))+'</small></li>'}).join('');
   var notes=(nh?'<ul class="adm-notes">'+nh+'</ul>':'')+'<button type="button" class="adm-lnk" data-p="notes"'+T('notes')+'>'+(ns.length?'All notes ('+ns.length+') / add':'Add a note')+'</button>';
   var rem='';if(act&&x.balance_due>0){rem=mt.reminders_paused?'<span class="adm-nw">Paused'+(mt.reminders_paused_until?' until '+E(d(mt.reminders_paused_until)):'')+'</span>'+(mt.pause_reason?'<span class="adm-mut adm-blk">'+E(mt.pause_reason)+'</span>':''):'<span class="adm-nw">'+(x.reminder_stage>=3?'All 3 reminders sent':x.reminder_stage?'Reminder '+x.reminder_stage+' of 3 sent':'Automatic, none sent yet')+'</span>';rem+=' <button type="button" class="adm-lnk" data-p="'+(mt.reminders_paused?'resume':'pause')+'"'+T(mt.reminders_paused?'resumeRem':'pauseRem')+'>'+(mt.reminders_paused?'Resume':'Pause')+'</button>'}
   function row(k,v,h){return v?'<div class="adm-r"><dt>'+lab(h,k)+'</dt><dd>'+v+'</dd></div>':''}
   var html='<section class="adm-sec adm-sec-class"><h4 class="adm-sh">'+lab('secClass','Class, notes and tags')+'</h4><dl class="adm-dl">'+row('Batch',bsel,'batchPick')+row('Attendance',att,'att')+row('Tags',tags,'tags')+row('Notes',notes,'notes')+row('Fee reminders',rem,'rem')+'</dl></section>';
   var first=secs.querySelector('.adm-sec');if(first)first.insertAdjacentHTML('afterend',html);else secs.insertAdjacentHTML('afterbegin',html)}
  // adjustments in the fee section
  var fs=card.querySelector('.adm-sec-fee');if(fs&&!pend){var aj=card._adjs;var ah=aj.length?'<ol class="adm-sched adm-hist">'+aj.map(function(a){return '<li'+(a.voided_at?' class="adm-void"':'')+'><span class="adm-nw">'+E(d(a.adj_date))+'</span><b class="adm-nw">'+(a.kind==='refund'?'− ':'')+E(pk(a.amount))+'</b><span class="adm-tag">'+ADJ[a.kind]+'</span><span class="adm-mut adm-nw">'+E(a.receipt_no||'')+'</span><span class="adm-mut">'+E(a.reason)+' · approved by '+E(a.approved_by)+'</span>'+(a.voided_at?'<span class="adm-fee od"'+T('Void: '+(a.void_reason||''))+'>Void</span>':'<button type="button" class="adm-lnk" data-p="adj-print" data-adj="'+a.id+'" title="Open a printable receipt for this '+a.kind+'.">Receipt</button>'+(ADMIN?'<button type="button" class="adm-lnk" data-p="adj-void" data-adj="'+a.id+'" title="Cancel this '+a.kind+' (entered by mistake). It stays in the list marked Void'+(a.kind==='refund'?'':' and the total fee goes back up')+'.">Void</button>':''))+'</li>'}).join('')+'</ol>':'';
   var refunded=aj.filter(function(a){return a.kind==='refund'&&!a.voided_at}).reduce(function(s,a){return s+a.amount},0);
   if(ah){var dl=fs.querySelector('.adm-dl');var rowh='<div class="adm-r"><dt>'+lab('adj','Adjustments')+'</dt><dd>'+(refunded?'<span class="adm-blk">Refunded '+E(pk(refunded))+' · net received <b>'+E(pk((x.amount_paid||0)-refunded))+'</b></span>':'')+ah+'</dd></div>';if(dl)dl.insertAdjacentHTML('beforeend',rowh);else fs.insertAdjacentHTML('beforeend','<dl class="adm-dl">'+rowh+'</dl>')}
   if(ADMIN&&x.invoice_no){var ba=fs.querySelector('.adm-acts');var bh='<button type="button" class="btn outline sm" data-p="adjust"'+T('adjBtn')+'>Discount / refund</button>';if(ba)ba.insertAdjacentHTML('beforeend',bh);else fs.insertAdjacentHTML('beforeend','<div class="adm-acts">'+bh+'</div>')}}
  // More menu: destructive actions move here (typed confirm), plus history, reminders pause and TEST
  card.querySelectorAll('.adm-cf [data-a=rev],.adm-acts [data-a=rev],[data-a=crev][data-u="0"]').forEach(function(b){b.remove()});
  var items=[['history','Activity history','hist2']];
  if(act&&x.balance_due>0)items.push(mt.reminders_paused?['resume','Resume fee reminders','resumeRem']:['pause','Pause fee reminders','pauseRem']);
  if(ADMIN){items.push(mt.is_test?['untest','Remove TEST mark','unmarkTest']:['test','Mark as TEST record','markTest']);
   if(x.certificate_no&&!x.certificate_revoked_at)items.push(['crev','Revoke certificate…','crevM','danger']);
   if(act)items.push(['revoke','Revoke access…','revokeM','danger']);if(x.status==='revoked')items.push(['restore','Restore access…','restoreM']);
   if(pend)items.push(['remove','Remove registration…','removeM','danger']);if(mt.is_test)items.push(['deltest','Delete TEST record…','delTest','danger'])}
  var foot=card.querySelector('.adm-cf');if(!foot){foot=document.createElement('footer');foot.className='adm-cf';card.appendChild(foot)}foot.innerHTML='';
  foot.insertAdjacentHTML('beforeend','<details class="adm-more"><summary class="btn outline sm"'+T('more')+'>More actions ▾</summary><div class="adm-menu" role="menu">'+items.map(function(i){return '<button type="button" role="menuitem" class="adm-mi'+(i[3]?' danger':'')+'" data-p="'+i[0]+'"'+T(i[2])+'>'+i[1]+'</button>'}).join('')+'</div></details>')});
 if(!B._proWired){B._proWired=true;B.addEventListener('click',function(ev){var el=ev.target.closest&&ev.target.closest('[data-p]');if(!el||el.tagName==='SELECT'||!B.contains(el))return;var card=el.closest('.adm-card');if(!card||!card._x)return;var dm=el.closest('details.adm-more');if(dm)dm.open=false;cardAction(el.dataset.p,el,card,B._refresh)});
  B.addEventListener('change',function(ev){var el=ev.target;if(el.dataset&&el.dataset.p==='batch'){var card=el.closest('.adm-card');assignBatch([card._x.id],el.value||null,B._refresh,function(){el.value=card._x.batch_id||''})}})}
 B._refresh=refresh;B._pays=PAYS}
document.addEventListener('click',function(ev){document.querySelectorAll('details.adm-more[open]').forEach(function(dm){if(!dm.contains(ev.target))dm.open=false})});
document.addEventListener('keydown',function(ev){if(ev.key==='Escape')document.querySelectorAll('details.adm-more[open]').forEach(function(dm){dm.open=false})});

async function assignBatch(ids,bid,after,undo,force){var r=await inv('pro_assign_batch',{ids:ids,batch_id:bid?+bid:null,force:!!force});
 if(r.data&&r.data.ok){toast(bid?'Batch saved':'Removed from batch');invalidate();after&&after();return true}
 var c=r.data&&r.data.code;if((c==='full'||c==='course')&&confirm(r.data.error+'\n\nDo it anyway?'))return assignBatch(ids,bid,after,undo,true);
 if(!(c==='full'||c==='course'))alert(err(r,'Could not change the batch.'));undo&&undo();return false}

async function cardAction(a,el,card,refresh){var x=card&&card._x,mt=card&&card._meta||{};refresh=refresh||function(){};
 if(a==='proof-view')return openProof(+el.dataset.pid);
 if(a==='proof-add'){var pays=(body()._pays||{})[x.id]||[],p=pays.find(function(y){return y.id===+el.dataset.pid});if(p)proofDlg(p,refresh);return}
 if(a==='history')return historyDlg(x);
 if(a==='notes')return notesDlg(x,card._notes,refresh);
 if(a==='tags')return tagsDlg(x,mt,refresh);
 if(a==='pause')return pauseDlg(x,refresh);
 if(a==='resume'){var r0=await sb.from('student_meta').upsert({enrollment_id:x.id,reminders_paused:false},{onConflict:'enrollment_id'});if(r0.error)return alert(r0.error.message);toast('Fee reminders resumed');return refresh()}
 if(a==='adjust')return adjustDlg(x,refresh);
 if(a==='adj-print'){var aj=card._adjs.find(function(y){return y.id===+el.dataset.adj});return printAdj(x,aj)}
 if(a==='adj-void'){var av=card._adjs.find(function(y){return y.id===+el.dataset.adj});var cv=await confirmDlg({title:'Void '+av.kind+' '+av.receipt_no,html:'<p>'+E(ADJ[av.kind])+' of <b>'+E(pk(av.amount))+'</b> will be marked Void.'+(av.kind==='refund'?'':' The total fee goes back up by this amount.')+'</p>',reason:true,ok:'Void it'});if(!cv)return;if(await runIn(cv,function(){return inv('pro_adjust_void',{adjustment_id:av.id,reason:cv.reason})})){toast('Voided');refresh()}return}
 if(a==='test'||a==='untest'){var on=a==='test';if(!confirm(on?'Mark '+(x.full_name||x.email)+' as a TEST record? It will be left out of the dashboard, exports and reminders.':'Remove the TEST mark? This record will count as a real student again.'))return;var rt=await inv('pro_mark_test',{id:x.id,on:on});if(!(rt.data&&rt.data.ok))return alert(err(rt,'Could not save.'));toast(on?'Marked as TEST':'TEST mark removed');invalidate();return refresh()}
 var who='<b>'+E(x.full_name||x.email)+'</b>'+(x.student_id?' ('+E(x.student_id)+')':'');
 if(a==='revoke'){var c1=await confirmDlg({title:'Revoke access',html:'<p>'+who+' will lose portal and book access now. Their record, payments and documents stay, and you can restore access later.</p>',word:'REVOKE',reason:true,ok:'Revoke access'});if(!c1)return;if(await runIn(c1,function(){return inv('pro_revoke',{id:x.id,reason:c1.reason,confirm:c1.word})})){toast('Access revoked');invalidate();refresh()}return}
 if(a==='restore'){var c2=await confirmDlg({title:'Restore access',html:'<p>'+who+' gets portal and book access again. The access end date is worked out again from the course length.</p>',reason:true,ok:'Restore access'});if(!c2)return;if(await runIn(c2,function(){return inv('pro_restore',{id:x.id,reason:c2.reason})})){toast('Access restored');invalidate();refresh()}return}
 if(a==='crev'){var c3=await confirmDlg({title:'Revoke certificate '+(x.certificate_no||''),html:'<p>The verify page will stop showing the certificate of '+who+' as valid. You can restore it later.</p>',word:'REVOKE',reason:true,ok:'Revoke certificate'});if(!c3)return;
  if(await runIn(c3,function(){return inv('cert_revoke',{id:x.id,undo:false,reason:c3.reason,confirm:c3.word})})){toast('Certificate revoked');refresh()}return}
 if(a==='remove'){var c4=await confirmDlg({title:'Remove registration',html:'<p>The pending registration of '+who+' will be deleted for good. Use this for spam or duplicates only.</p>',word:'DELETE',reason:true,ok:'Delete registration'});if(!c4)return;if(await runIn(c4,function(){return inv('pro_remove',{id:x.id,reason:c4.reason,confirm:c4.word})})){toast('Registration removed');invalidate();refresh()}return}
 if(a==='deltest'){var c5=await confirmDlg({title:'Delete TEST record',html:'<p>'+who+' is marked TEST. The record, its payments, notes, attendance and its PDF files in the portal storage will be deleted for good. Google Drive copies are not touched.</p>',word:'DELETE',ok:'Delete for good'});if(!c5)return;if(await runIn(c5,function(){return inv('pro_delete_test',{ids:[x.id],confirm:c5.word})})){toast('TEST record deleted');invalidate();refresh()}return}}

/* ---------- small dialogs ---------- */
function notesDlg(x,notes,after){var me=A.me&&A.me.id;
 var list=notes.length?'<ul class="adm-notes adm-notes-full">'+notes.map(function(n){var mine=ADMIN||n.created_by===me;return '<li data-n="'+n.id+'"'+(n.pinned?' class="pin"':'')+'><span>'+E(n.body)+'</span><small class="adm-mut">'+E(dt(n.created_at))+(n.updated_at?' · edited':'')+'</small>'+(mine?'<span class="adm-nact"><button type="button" class="adm-lnk" data-na="pin" title="'+(n.pinned?'Unpin this note.':'Pin this note so it always shows first on the card.')+'">'+(n.pinned?'Unpin':'Pin')+'</button><button type="button" class="adm-lnk" data-na="del" title="Delete this note.">Delete</button></span>':'')+'</li>'}).join('')+'</ul>':'<p class="adm-mut">No notes yet.</p>';
 var g=dlg('<h3>Notes · '+E(x.full_name||x.email)+'</h3><p class="adm-mut">Internal notes for staff. The student never sees them.</p>'+list+'<label class="adm-fl">New note<textarea name="note" rows="3" maxlength="2000" placeholder="e.g. Pays on the 5th of every month"'+T('notes')+'></textarea></label><label class="adm-ck" title="Show this note first on the card."><input type="checkbox" name="pin"> Pin this note</label>');
 g.classList.add('adm-wide');var f=g.querySelector('form'),m=g.querySelector('.adm-dmsg'),ok=f.querySelector('[value=ok]');ok.textContent='Add note';f.querySelector('[value=cancel]').textContent='Close';var changed=false;
 g.addEventListener('close',function(){if(changed)after()});
 f.addEventListener('click',async function(ev){var b=ev.target.closest('[data-na]');if(!b)return;ev.preventDefault();var li=b.closest('[data-n]'),nid=+li.dataset.n,n=notes.find(function(y){return y.id===nid});
  if(b.dataset.na==='del'){if(!confirm('Delete this note?'))return;var r=await sb.from('student_notes').delete().eq('id',nid);if(r.error)return alert(r.error.message);li.remove();changed=true}
  else{var r2=await sb.from('student_notes').update({pinned:!n.pinned}).eq('id',nid);if(r2.error)return alert(r2.error.message);n.pinned=!n.pinned;li.classList.toggle('pin',n.pinned);b.textContent=n.pinned?'Unpin':'Pin';changed=true}});
 f.onsubmit=async function(ev){if(ev.submitter&&ev.submitter.value==='cancel')return;ev.preventDefault();var t=f.note.value.trim();if(!t){m.textContent='Write the note first.';return}ok.disabled=true;
  var r=await sb.from('student_notes').insert({enrollment_id:x.id,body:t,pinned:f.pin.checked,created_by:me});ok.disabled=false;if(r.error){m.textContent=r.error.message;return}changed=true;g.close();toast('Note added')}}
