async function dashboardTab(){var B=body();B.innerHTML='<h3>Dashboard</h3>'+skel(6);var r=await inv('pro_dashboard');if(!r.data||!r.data.ok){B.innerHTML='<p>'+E(err(r,'Could not load the dashboard.'))+'</p>';return}var D=r.data;
 var month=new Date(D.today+'T00:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
 function tile(v,t,k,cls,go){return '<'+(go?'button type="button" data-go="'+go+'"':'div')+' class="adm-card sec-tile dash-tile'+(cls?' '+cls:'')+'"'+T(k)+'><b>'+v+'</b><span class="adm-mut">'+t+'</span></'+(go?'button':'div')+'>'}
 var diff=D.collected_month-D.collected_prev;
 var max=Math.max.apply(null,D.months.map(function(m){return Math.abs(m.net)}).concat([1]));
 var chart='<div class="adm-card dash-chart"'+T('dbChart')+'><h4>Received per month</h4><div class="dash-bars">'+D.months.map(function(m){var h=Math.max(2,Math.round(100*Math.max(m.net,0)/max));return '<div class="dash-bar"><span class="dash-v">'+(m.net?num(Math.round(m.net/1000))+'k':'0')+'</span><i style="height:'+h+'%"></i><small>'+new Date(m.month+'-01T00:00:00').toLocaleDateString('en-GB',{month:'short'})+'</small></div>'}).join('')+'</div></div>';
 var meth=Object.keys(D.by_method);var mtot=meth.reduce(function(s,k){return s+D.by_method[k]},0);
 var methods='<div class="adm-card dash-chart"'+T('dbMethod')+'><h4>How it was paid ('+month+')</h4>'+(meth.length?'<ul class="dash-meth">'+meth.sort(function(a,b){return D.by_method[b]-D.by_method[a]}).map(function(k){var pc=Math.round(100*D.by_method[k]/(mtot||1));return '<li><span>'+E(A.P.METHODS[k]||k)+'</span><b>'+pk(D.by_method[k])+'</b><i style="width:'+pc+'%"></i></li>'}).join('')+'</ul>':'<p class="adm-mut">No payments yet this month.</p>')+'</div>';
 function lst(rows,kind){if(!rows.length)return '<p class="adm-mut">'+(kind==='od'?'Nobody is overdue.':'No payments due in the next 7 days.')+'</p>';
  return '<div class="adm-scroll"><table class="adm"><thead><tr><th>Student</th><th>Batch</th><th>Balance</th><th>'+(kind==='od'?'Was due':'Due')+'</th><th></th></tr></thead><tbody>'+rows.map(function(x){return '<tr><td data-l="Student"><button type="button" class="adm-lnk" data-open="'+E(x.student_id||x.name||'')+'"'+T('open')+'>'+E(x.name||'–')+'</button><small class="adm-mut adm-blk">'+E(x.student_id||'')+'</small></td><td data-l="Batch">'+E(x.batch||'–')+'</td><td data-l="Balance"><b>'+pk(x.balance)+'</b></td><td data-l="Due" class="adm-nw">'+E(d(x.due))+(kind==='od'?' <span class="adm-fee od">'+x.days+' day'+(x.days===1?'':'s')+' late</span>':'')+'</td><td class="adm-a" data-l="Remind">'+(x.has_phone?'<button type="button" class="btn sm adm-wa" data-wa="'+x.id+'"'+T('waRem')+'>WhatsApp</button>':'')+'<button type="button" class="btn outline sm" data-mr="'+x.id+'"'+T('mailRem')+'>Email reminder</button></td></tr>'}).join('')+'</tbody></table></div>'}
 B.innerHTML='<h3>Dashboard</h3><p class="adm-mut">'+E(month)+' · Pakistan time · TEST records left out'+(D.tests?' ('+D.tests+')':'')+'.</p><div class="sec-tiles dash-tiles">'+
  tile(pk(D.collected_month),'received this month'+(D.collected_prev||D.collected_month?'<small class="adm-blk '+(diff>=0?'up':'down')+'">'+(diff>=0?'▲ ':'▼ ')+pk(Math.abs(diff))+' vs last month</small>':''),'dbCollected','ok')+
  tile(pk(D.outstanding),'still to be paid','dbOutstanding','','fee pending')+tile(D.overdue.length+' · '+pk(D.overdue_total),'overdue','dbOverdue',D.overdue.length?'warn':'','overdue')+tile(D.soon.length,'due in the next 7 days','dbSoon')+
  tile(D.pending,'waiting for payment confirmation','dbPending',D.pending?'warn':'','pending')+tile(D.active,'active students','dbActive','','active')+tile(D.new_month,'new registrations this month','dbNew')+(D.refunds_month?tile(pk(D.refunds_month),'refunded this month','dbRefunds'):'')+'</div>'+
  '<div class="dash-grid">'+chart+methods+'</div><section class="adm-card dash-list"><h4>'+lab('dbOverdue','Overdue')+'</h4>'+lst(D.overdue,'od')+'</section><section class="adm-card dash-list"><h4>'+lab('dbSoon','Due in the next 7 days')+'</h4>'+lst(D.soon,'soon')+'</section>';
 B.querySelectorAll('[data-go]').forEach(function(b){b.onclick=function(){A.openFilter(b.dataset.go)}});
 B.querySelectorAll('[data-wa]').forEach(function(b){b.onclick=function(){openWaReminder(+b.dataset.wa)}});B.querySelectorAll('[data-mr]').forEach(function(b){b.onclick=function(){mailReminder(+b.dataset.mr,b)}})}

