function staffInviteDlg(again){
  var g=dlg('<h3>Add a staff member</h3><label>Name <input name="n" required maxlength="100" autocomplete="name"'+T('staffName')+'></label><label>Email <input name="e" type="email" required maxlength="120" autocomplete="email"'+T('staffEmail')+'></label><p class="adm-mut">They will get an email to set their own password. No password is shown here. After they are added, everything is off until you switch on their permissions.</p>');
  var f=g.querySelector('form'),m=g.querySelector('.adm-dmsg'),ok=f.querySelector('[value=ok]');ok.textContent='Send invite';
  f.onsubmit=async function(ev){if(ev.submitter&&ev.submitter.value==='cancel')return;ev.preventDefault();if(!f.reportValidity())return;ok.disabled=true;m.textContent='Sending the invite…';
    var r=await inv('pro_staff_invite',{full_name:f.n.value.trim(),email:f.e.value.trim()});ok.disabled=false;
    if(!(r.data&&r.data.ok)){m.textContent=err(r,'Could not send the invite.');return}
    g.close();toast('Invite sent. Set their permissions next.');if(again)again()}
}
