function safeCell(v){if(v==null)return '';if(typeof v==='number'||typeof v==='boolean')return v;var s=String(v);return /^[=+\-@\t\r]/.test(s)?"'"+s:s}
function toCsv(rows){if(!rows.length)return '';var k=Object.keys(rows[0]);function q(v){v=safeCell(v);v=String(v);return /[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}return '\ufeff'+[k.map(q).join(',')].concat(rows.map(function(r){return k.map(function(c){return q(r[c])}).join(',')})).join('\r\n')}
function saveBlob(blob,name){var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove()},1500)}
