var XLSX_SRC='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js',XLSX_SRI='sha384-vtjasyidUo0kW94K5MXDXntzOJpQgBKXmE7e2Ga4LG0skTTLeBi97eFAXsqewJjw';
var XLSXp=null;function loadXlsx(){if(window.XLSX)return Promise.resolve(window.XLSX);if(XLSXp)return XLSXp;XLSXp=new Promise(function(res,rej){var s=document.createElement('script');s.src=XLSX_SRC;s.integrity=XLSX_SRI;s.crossOrigin='anonymous';s.referrerPolicy='no-referrer';s.onload=function(){window.XLSX?res(window.XLSX):rej(new Error('Excel library did not load.'))};s.onerror=function(){XLSXp=null;rej(new Error('Could not load the Excel library. Try CSV instead.'))};document.head.appendChild(s)});return XLSXp}
async function fetchAll(mk){var out=[],from=0,step=1000;for(;;){var r=await mk().range(from,from+step-1);if(r.error)throw new Error(r.error.message);out=out.concat(r.data||[]);if(!r.data||r.data.length<step)break;from+=step;if(from>50000)break}return out}
